    private static readonly IconData[] Catalog = BuildCatalog();

    private static IconData[] BuildCatalog()
    {
        var directional = new bool[CatalogCodePoints.Length];
        foreach (int index in DirectionalIndexes)
        {
            directional[index] = true;
        }

        var catalog = new IconData[CatalogCodePoints.Length];
        for (int index = 0; index < catalog.Length; index++)
        {
            catalog[index] = new IconData(
                CatalogCodePoints[index],
                FontFamily: IconFont,
                MatchTextDirection: directional[index]);
        }

        return catalog;
    }
